/* From Uiverse.io by simontheonlyone - Source: Apple - https://www.apple.com/ - Tags: card, note, inote */
.__UIV_SCOPE__ .card {
  position: relative;
  width: 150px;
  height: 150px;
  background: linear-gradient(
    to bottom,
    rgb(253, 197, 107) 12%, rgb(255, 187, 78) 24%,
    rgba(0, 0, 0, .3) 25%, rgba(0, 0, 0, .1) 26% 26%,
    #eee 28% 49%,
    rgba(0, 0, 0, .3) 50%,
    #eee 51% 74%,
    rgba(0, 0, 0, .3) 75%,
    #eee 76%
  );
  border: none;
  border-radius: 35px;
  box-shadow: 0 0 10px rgba(0, 0, 0, .3);
  overflow: hidden;
}

.__UIV_SCOPE__ .dots {
  position: absolute;
  content: '';
  inset: 0 -3px;
  color: rgba(0, 0, 0, .3);
  font-size: 41px;
  user-select: none;
  -webkit-user-select: none;
}
